const grid=document.querySelector('#project-grid');
grid.innerHTML=projects.map((p,i)=>`<article class="project-card" data-category="${p.category}" aria-labelledby="project-title-${p.id}"><button class="project-art ${p.id}" data-project="${p.id}" aria-label="Read about ${p.name}"><span class="project-number">PROJECT / ${String(i+1).padStart(2,'0')}</span>${p.image?`<img src="${p.image}" width="1200" height="900" alt="${p.alt}" loading="lazy">`:`<div aria-hidden="true">${p.art}</div>`}<span class="project-open" aria-hidden="true">↗</span></button><div class="project-info"><div><h3 id="project-title-${p.id}">${p.name}</h3><p>${p.subtitle}</p></div><span class="project-type">${p.type}</span><p class="project-summary">${p.description}</p><div class="tags">${p.tags.slice(0,4).map(t=>`<span>${t}</span>`).join('')}</div><button class="project-detail-link" data-project="${p.id}">Explore project <span aria-hidden="true">↗</span></button></div></article>`).join('');
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
 document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});
 let count=0;document.querySelectorAll('.project-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;if(!card.hidden)count++;});
 document.querySelector('#filter-status').textContent=`Showing ${count} projects`;
}));
const dialog=document.querySelector('#project-dialog');
let trigger=null;
grid.addEventListener('click',event=>{
 const button=event.target.closest('[data-project]');if(!button)return;
 const p=projects.find(item=>item.id===button.dataset.project);trigger=button;
 document.querySelector('#dialog-content').innerHTML=`<span class="eyebrow">${p.type}</span><h2 id="dialog-title" class="dialog-heading">${p.name}</h2><p>${p.description}</p><ul>${p.highlights.map(h=>`<li>${h}</li>`).join('')}</ul><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div>${!p.image?'<p class="dialog-note">Cover artwork is an editorial illustration of the project.</p>':''}`;
 dialog.showModal();document.body.classList.add('modal-open');
});
let closingProject=false;
async function closeProject(){
 if(closingProject||!dialog.open)return;closingProject=true;
 if(!document.body.classList.contains('motion-off')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
  await dialog.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(15px)'}],{duration:180,easing:'ease-in'}).finished.catch(()=>{});
 }
 dialog.close();closingProject=false;
}
document.querySelector('.dialog-close').addEventListener('click',closeProject);
dialog.addEventListener('cancel',event=>{event.preventDefault();closeProject();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeProject();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');trigger?.focus();});
